#include <iostream>
#include <vector>

struct Item {
    int key;
    int original;
};

int main() {
    int n;
    if (!(std::cin >> n) || n < 0 || n > 32) {
        std::cout << "invalid\n";
        return 0;
    }
    std::vector<Item> records;
    for (int i = 0; i < n; ++i) {
        int key;
        if (!(std::cin >> key) || key < -9999 || key > 9999) {
            std::cout << "invalid\n";
            return 0;
        }
        records.push_back({key, i});
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }

    // TODO: Вставьте каждую запись в готовый префикс, сохраняя порядок
    // равных ключей.
    for (std::size_t i = 0; i < records.size(); ++i) {
        if (i != 0) {
            std::cout << ' ';
        }
        std::cout << records[i].key << ':' << records[i].original;
    }
    std::cout << '\n';
}
